# Independent literal-spec reference (naive, for small cases only).
def ref(nodes, links, cap_of, packets):
    import math
    adj={}
    for l in links:
        if l['up']:
            adj.setdefault(l['from'],[]).append((l['to'],l['cost']))
    def dijkstra(s):
        import itertools
        # brute force Dijkstra with explicit best-path tie-break
        best={s:(0,[s])}
        settled=set()
        while True:
            u=None
            for n in nodes:
                if n in best and n not in settled and (u is None or best[n][0]<best[u][0]):
                    u=n
            if u is None: break
            settled.add(u)
            c,p=best[u]
            for v,w in adj.get(u,()):
                if v in settled: continue
                nc=c+w; np=p+[v]
                if v not in best or nc<best[v][0] or (nc==best[v][0] and np<best[v][1]):
                    best[v]=(nc,np)
        return best

    paths=[None]*len(packets)
    cache={}
    for i,(pid,t,s,d,sz) in enumerate(packets):
        if s not in cache: cache[s]=dijkstra(s)
        if d in cache[s]: paths[i]=list(cache[s][d][1])

    E=len(links)
    lk={(l['from'],l['to']):k for k,l in enumerate(links)}
    occ=[0]*E; q=[[] for _ in range(E)]; busy=[None]*E
    adm=[0]*E; ovf=[0]*E; peak=[0]*E; last=[0]*E
    res=[[pid,None,None,None,None,None,[]] for pid,_,_,_,_ in packets]
    hopk=[0]*len(packets)
    for i,(pid,t,s,d,sz) in enumerate(packets):
        if paths[i] is None:
            if s==d: res[i][1:5]=['delivered',[s],t,0]
            else: res[i][1]='unreachable'; res[i][2]=[]
    # events: completions set; arrivals dict time -> list of (DATA idx, kind)
    arrivals={}
    completions={}
    # prime injections
    for i,(pid,t,s,d,sz) in enumerate(packets):
        if paths[i] is not None:
            arrivals.setdefault(t,[]).append((i,'inj'))
    def admit(i,now,kind):
        p=paths[i]; k=hopk[i]
        fr,to=p[k],p[k+1]; li=lk[(fr,to)]
        h={'from':fr,'to':to,'arrive':now,'start':None,'depart':None,'receive':None,'wait':None}
        res[i][6].append(h)
        sz=packets[i][4]
        if occ[li]+sz>cap_of[li]:
            res[i][1]='overflow'; res[i][5]=[fr,to]; ovf[li]+=1
        else:
            occ[li]+=sz; peak[li]=max(peak[li],occ[li]); adm[li]+=1
            q[li].append(i)
    times=set(arrivals)|set(completions)
    while times:
        now=min(times)
        progress=True
        while progress:
            progress=False
            # phase 1: completions
            for (dep,li),i in sorted(completions.items()):
                if dep!=now: continue
                del completions[(dep,li)]
                sz=packets[i][4]; occ[li]-=sz; busy[li]=None; last[li]=now
                p=paths[i]; k=hopk[i]
                rec=now+links[li]['latency']
                res[i][6][-1]['receive']=rec
                if k+1==len(p)-1:
                    res[i][1]='delivered'; res[i][3]=rec; res[i][4]=rec-packets[i][1]
                else:
                    hopk[i]+=1
                    arrivals.setdefault(rec,[]).append((i,'recv'))
                progress=True
            # phase 2: arrivals in DATA order
            evs=arrivals.pop(now,[])
            evs.sort(key=lambda x:x[0])
            for i,kind in evs:
                admit(i,now,kind); progress=True
            # phase 3: start idle in FILE order
            for li in range(E):
                if busy[li] is None and q[li]:
                    i=q[li].pop(0)
                    sz=packets[i][4]
                    dur=(sz+links[li]['bandwidth']-1)//links[li]['bandwidth']
                    dep=now+dur; busy[li]=dep
                    h=res[i][6][-1]
                    h['start']=now; h['depart']=dep; h['wait']=now-h['arrive']
                    completions[(dep,li)]=i
                    progress=True
        times=set(arrivals)|set(completions)
    for i in range(len(packets)):
        if paths[i] is not None: res[i][2]=paths[i]
    return {'packets':res,'links':[[links[k]['from'],links[k]['to'],adm[k],ovf[k],peak[k],last[k]] for k in range(E)]}
