    packets = []
    seen_ids = set()
    previous_time = None
    for item in data:
        if not isinstance(item, list) or len(item) != 5:
            fail(5)
        pid, time, source, destination, size = item
        if (type(pid) is not str or pid == ""
                or not 1 <= len(pid) <= MAX_FLOW_LEN
                or pid in seen_ids):
            fail(5)
        try:
            pid.encode("utf-8")
        except UnicodeEncodeError:
            fail(5)
        seen_ids.add(pid)
        if type(time) is not int or not 0 <= time <= MAX_TIME:
            fail(5)
        if previous_time is not None and time < previous_time:
            fail(5)
        previous_time = time
        if source not in node_set or destination not in node_set:
            fail(5)
        if type(size) is not int or not 1 <= size <= MAX_COST:
            fail(5)
        packets.append((pid, time, source, destination, size))
    result = compute_netqueue(nodes, links, cap_of, packets)
elif argv[1] == "converge":
    if len(argv) != 8:
        fail(2)
    file_path, source, destination = argv[2], argv[3], argv[4]
    delay_text, run_text, events_text = argv[5], argv[6], argv[7]
    nodes, links, node_set = load_network(file_path, strict=True)
    if source not in node_set or destination not in node_set:
        fail(5)
    delay = _bounded_int_arg(delay_text)
